(function(){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let scope='preview';
const get=(k,d='')=>{try{return localStorage.getItem('dba-tool-'+scope+'-'+k)||d}catch{return d}};
const store=(k,v)=>{try{localStorage.setItem('dba-tool-'+scope+'-'+k,v)}catch{window.AcademyUI?.toast('This browser could not save your tool draft. Export it before leaving.')}};
function download(name,text,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const DEFAULT_WEB='<!doctype html>\n<html lang="en">\n<head>\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<style>body{font:18px system-ui;margin:32px;line-height:1.6}main{max-width:640px;margin:auto}a{color:#c9260e}</style>\n</head>\n<body>\n<main>\n  <h1>A little café. A warm welcome.</h1>\n  <p>Fresh food, good company, and a place to pause.</p>\n  <a href="mailto:hello@example.test">Ask about our menu</a>\n</main>\n</body>\n</html>';
const tools=[['notebook','Writing desk','A private editor for briefs, research, handovers and notes.','Pen'],['web','Web studio','Write HTML, CSS and JavaScript in an isolated browser preview.','Code'],['data','Data desk','Inspect CSV values, calculate a total and query practice tables.','Chart'],['prompt','Prompt studio','Prepare a reusable AI brief and inspect its structure.','Spark'],['flow','Automation lab','Simulate validation, duplicates, approval and bounded retries.','Workflow'],['api','API console','Explore request validation and ownership using fictional bookings.','Terminal']];
function field(label,id,value,opts=''){return `<label class="field"><span>${label}</span><textarea id="${id}" ${opts}>${esc(value)}</textarea></label>`}
function render(id){
 const tool=tools.find(x=>x[0]===id)||tools[0];let body='';
 if(id==='web')body=`<div class="studio-grid"><div>${field('Your HTML, CSS and JavaScript','tool-web',get('web',DEFAULT_WEB),'class="code-editor" spellcheck="false"')}<div class="row"><button class="btn primary" data-studio="web-run">Run preview</button><button class="btn" data-studio="web-export">Export HTML</button></div><p class="tool-note">Isolated preview. Network calls and access to Academy storage are blocked.</p></div><div><div class="row between" style="margin-bottom:12px"><b>Live preview</b><span class="status">Browser sandbox</span></div><div class="tool-result" id="tool-output"><p class="muted">Run your code to see the result.</p></div></div></div>`;
 else if(id==='data')body=`<div class="studio-grid"><section>${field('CSV data · one numeric amount per row','tool-data',get('data','item,amount\nCoffee,120\nTea,80\nRefund,-20'),'class="code-editor" spellcheck="false"')}<button class="btn primary" data-studio="data-run">Calculate summary</button><p class="tool-note">Two-column CSV trainer. Quoted values, commas and empty rows are validated. It is not a full spreadsheet.</p></section><section><label class="field"><span>SQL practice · orders or bookings</span><textarea class="code-editor" id="tool-sql" style="min-height:120px">${esc(get('sql','SELECT id, customer, status FROM orders'))}</textarea></label><button class="btn" data-studio="sql-run">Run SELECT query</button><div class="tool-result" id="tool-output" style="min-height:150px;margin-top:20px">Your results will appear here.</div></section></div>`;
 else if(id==='prompt')body=`<div class="studio-grid"><div>${[['task','Task and audience','Write an opening announcement for a fictional café, aimed at nearby office workers.'],['context','Approved facts','Name: Olive Café. Opening: Monday. Menu: coffee and lunch. Opening hours are not confirmed.'],['rules','Boundaries','Do not invent opening hours, prices, awards or customer reviews. Use no private information.'],['format','Output and evaluation','Return a 60-word announcement and a list of facts that still need confirmation.']].map(([k,l,d])=>field(l,'prompt-'+k,get('prompt-'+k,d),'style="min-height:90px"')).join('')}<div class="row"><button class="btn primary" data-studio="prompt-run">Build my prompt</button><button class="btn" data-studio="prompt-export">Export prompt</button></div></div><div class="tool-result" id="tool-output"><h3>A better brief comes first</h3><p>This studio checks your instruction structure. It does not send data to an AI model or generate an answer.</p><p class="muted">Use fictional data, then test the prompt in your approved AI service and bring the observed result back to your recipe.</p></div></div>`;
 else if(id==='flow')body=`<div class="studio-grid"><div>${field('Workflow policy · edit the JSON','tool-flow',get('flow',JSON.stringify({steps:['validate','deduplicate','human_approval','record_result'],maxRetries:3,retryDelaySeconds:5,deadLetterOwner:'Operations lead'},null,2)),'class="code-editor" spellcheck="false"')}<div class="row"><button class="btn primary" data-studio="flow-run">Run simulation</button><button class="btn" data-studio="flow-export">Export policy</button></div><p class="tool-note">Fictional events only. This lab never sends email, creates purchases or contacts external systems.</p></div><div class="tool-result" id="tool-output">Run the policy to inspect validation, duplicate handling and approval boundaries.</div></div>`;
 else if(id==='api')body=`<div class="studio-grid"><div><label class="field"><span>Method</span><select id="api-method"><option>GET</option><option>POST</option></select></label><label class="field"><span>Resource</span><input id="api-path" value="/bookings/BK-100"></label><label class="field"><span>Fictional caller</span><select id="api-actor"><option>alice</option><option>bob</option></select></label>${field('JSON body for POST','api-body','{"customerId":"alice","service":"repair","quantity":1}','style="min-height:100px"')}<label class="field"><span>Request key</span><input id="api-key" value="my-request-1"></label><button class="btn primary" data-studio="api-run">Send simulated request</button></div><div class="tool-result" id="tool-output"><p>BK-100 belongs to Alice. Try reading it as Bob to inspect the denied-access response.</p><p class="small muted">GET /bookings/BK-100 or POST /bookings. Change the method and resource together.</p></div></div>`;
 else body=`${field('Private working document','tool-notebook',get('notebook','Project title:\n\nThe problem\n\nSource facts\n\nMy approach\n\nTest results\n\nHandover and limitations\n'),'style="min-height:430px"')}<div class="row"><button class="btn primary" data-studio="notebook-export">Export document</button><span class="small muted">Saved in this browser as you type.</span></div>`;
 return `<div class="workspace-tabs" aria-label="Workspace tools">${[...tools,...(window.AcademyStandard?.tools||[]).filter(t=>window.AcademyExtraStudio?.ids.includes(t[0]))].map(t=>`<a href="#studio/${t[0]}" class="${t[0]===tool[0]?'active':''}">${window.ToolIcons.icon(t[0],18)}${esc(t[1])}</a>`).join('')}</div><div class="panel"><div class="row between" style="margin-bottom:24px"><div><h2>${esc(tool[1])}</h2><p class="muted small" style="margin:0">${esc(tool[2])}</p></div><span class="status">${id==='api'||id==='flow'?'Practice simulation':'Private workspace'}</span></div>${body}</div>`;
}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if(c==='\n'&&!quoted){row.push(cell.replace(/\r$/,''));if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('A quoted CSV value is not closed.');row.push(cell.replace(/\r$/,''));if(row.some(x=>x.trim()))rows.push(row);return rows}
function table(rows){if(!rows.length)return '<p>No rows match this query.</p>';const keys=Object.keys(rows[0]);return `<div class="table-scroll"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
let apiState=null;
function promptText(){return ['task','context','rules','format'].map(k=>k.toUpperCase()+'\n'+document.getElementById('prompt-'+k).value).join('\n\n')}
async function handle(action){const out=document.getElementById('tool-output'),val=id=>document.getElementById(id)?.value||'';try{
 if(action==='web-run'){const code=val('tool-web'),doc=new DOMParser().parseFromString(code,'text/html');const policy=doc.createElement('meta');policy.httpEquiv='Content-Security-Policy';policy.content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src data:; connect-src 'none'; form-action 'none'; base-uri 'none'";doc.head.prepend(policy);out.innerHTML='<iframe title="Isolated web preview" sandbox="allow-scripts"></iframe>';out.querySelector('iframe').srcdoc='<!doctype html>'+doc.documentElement.outerHTML;store('web',code)}
 if(action==='web-export')download('my-website.html',val('tool-web'),'text/html');
 if(action==='notebook-export')download('my-project-notes.md',val('tool-notebook'),'text/markdown');
 if(action==='data-run'){const rows=parseCSV(val('tool-data'));if(rows.length<2||rows.some(r=>r.length!==2))throw Error('Use a header and at least one row, with two columns in every row.');let nums=rows.slice(1).map((r,i)=>{if(!r[1].trim()||!Number.isFinite(Number(r[1])))throw Error('Row '+(i+2)+' has a missing or invalid amount.');return Number(r[1])});out.innerHTML=`<h3>${nums.length} records · total ${nums.reduce((a,b)=>a+b,0).toFixed(2)}</h3><p class="small muted">Average ${(nums.reduce((a,b)=>a+b,0)/nums.length).toFixed(2)} · Minimum ${Math.min(...nums)} · Maximum ${Math.max(...nums)}</p>`+table(rows.slice(1).map(r=>({item:r[0],amount:r[1]})));store('data',val('tool-data'))}
 if(action==='sql-run'){out.innerHTML=table(window.AcademyEngines.query(val('tool-sql')));store('sql',val('tool-sql'))}
 if(action==='prompt-run'){const p=promptText(),missing=['task','context','rules','format'].filter(k=>val('prompt-'+k).trim().length<20);if(missing.length)throw Error('Add specific detail to: '+missing.join(', '));out.innerHTML='<h3>Your reusable prompt</h3><pre>'+esc(p)+'</pre><p class="small muted">Structure checked. Accuracy and usefulness still require a real output and human review.</p>'}
 if(action==='prompt-export')download('my-ai-brief.txt',promptText());
 if(action==='flow-run'){const r=window.AcademyEngines.workflow({}, {code:val('tool-flow'),fields:{}});out.innerHTML='<h3>'+ (r.pass?'Policy checks passed':'Improve your policy')+'</h3><pre>'+esc(JSON.stringify(r,null,2))+'</pre>';store('flow',val('tool-flow'))}
 if(action==='flow-export')download('workflow-policy.json',val('tool-flow'),'application/json');
 if(action==='api-run'){apiState=apiState||window.AcademyEngines.apiSeed();const result=window.AcademyEngines.request(apiState,{method:val('api-method'),path:val('api-path'),actor:val('api-actor'),body:val('api-body'),key:val('api-key')},{validation:true,ownership:true,idempotency:true});out.innerHTML='<h3>Simulated response</h3><pre>'+esc(JSON.stringify(result,null,2))+'</pre>'}
 }catch(e){if(out)out.innerHTML='<p class="notice error">'+esc(e.message)+'</p>';else window.AcademyUI?.toast(e.message)} }
function mount(){}
document.addEventListener('click',e=>{const b=e.target.closest('[data-studio]');if(b)handle(b.dataset.studio)});
document.addEventListener('input',e=>{const id=e.target.id;if(id?.startsWith('tool-'))store(id.slice(5),e.target.value);if(id?.startsWith('prompt-'))store(id,e.target.value);});
window.AcademyStudio={render,mount,tools,download,parseCSV,setScope:value=>{scope=value||'preview';apiState=null}};
})();
